class StructuredArgvExecutorError(Exception):
    """読み取り専用argv executorのfail-closed条件に触れた。"""

    def __init__(self, code, detail=None):
        super().__init__(f"{code}: {detail}" if detail else code)
        self.code = code
        self.detail = detail

